//#region src/stores/batchStore.ts
var DEFAULT_BATCH_CONFIG = {
	concurrency: 5,
	timeout: 30,
	onFailure: "continue"
};
var useBatchStore = defineStore("batch", () => {
	const sessions = /* @__PURE__ */ ref([]);
	const isExecuting = /* @__PURE__ */ ref(false);
	const config = /* @__PURE__ */ ref({ ...DEFAULT_BATCH_CONFIG });
	/** 用户主动取消或 onFailure=stop 触发的取消标志 */
	const cancelRequested = /* @__PURE__ */ ref(false);
	/** 初始化一批待执行的 session（清空旧结果） */
	function startBatch(hosts, cfg) {
		sessions.value = hosts.map((h) => ({
			hostId: h.hostId,
			hostName: h.hostName,
			hostSubtitle: h.hostSubtitle,
			status: "pending",
			output: ""
		}));
		config.value = { ...cfg };
		isExecuting.value = true;
		cancelRequested.value = false;
	}
	/** 更新指定主机的状态 */
	function updateSessionStatus(hostId, status, error) {
		const s = sessions.value.find((s) => s.hostId === hostId);
		if (!s) return;
		s.status = status;
		if (status === "running" && !s.startTime) s.startTime = Date.now();
		if (status === "success" || status === "failed") s.endTime = Date.now();
		if (error !== void 0) s.error = error;
	}
	/** 追加输出到指定主机 */
	function appendOutput(hostId, chunk) {
		const s = sessions.value.find((s) => s.hostId === hostId);
		if (s) s.output += chunk;
	}
	/** 请求取消（用户点击取消按钮或 onFailure=stop 触发） */
	function requestCancel() {
		cancelRequested.value = true;
	}
	/** 标记批量执行结束 */
	function finishBatch() {
		isExecuting.value = false;
		for (const s of sessions.value) if (s.status === "pending" || s.status === "running") {
			s.status = "failed";
			s.error = s.error || "Cancelled";
			s.endTime = Date.now();
		}
	}
	/** 清空结果（保留配置） */
	function clearResults() {
		sessions.value = [];
		isExecuting.value = false;
		cancelRequested.value = false;
	}
	/** 重置配置为默认值 */
	function resetConfig() {
		config.value = { ...DEFAULT_BATCH_CONFIG };
	}
	function countByStatus(status) {
		return sessions.value.filter((s) => s.status === status).length;
	}
	/** 已完成数（success + failed），用于进度显示 */
	function completedCount() {
		return countByStatus("success") + countByStatus("failed");
	}
	return {
		sessions,
		isExecuting,
		config,
		cancelRequested,
		startBatch,
		updateSessionStatus,
		appendOutput,
		requestCancel,
		finishBatch,
		clearResults,
		resetConfig,
		countByStatus,
		completedCount
	};
});
