	/\bdd\b[^|;&]*\bof=\/dev\//,
	/\bchmod\s+(-R\s+)?777\s+\/(?:\s|$|;|&|\|)/,
	/\bchmod\s+-R\s+000\s+\/(?:\s|$|;|&|\|)/,
	/\b(curl|wget)\b[^|;&]*\|\s*(sh|bash|zsh|fish|python|python3|perl|ruby)\b/,
	/:\(\)\s*\{\s*:\s*\|\s*:\s*&\s*\}\s*;\s*:/,
	/>\s*\/dev\/(?:sd|nvme|hd|vd|disk)/,
	/\b(shutdown|reboot|halt|poweroff)\b/,
	/\bkill\s+-9\s+1\b/,
	/\bkill\s+-KILL\s+1\b/,
	/\bkillall\b/,
	/\bpkill\s+-9\b/,
	/\bpkill\s+-KILL\b/
