	/\bmv\b/,
	/\bchmod\b/,
	/\bchown\b/,
	/\bmkdir\b/,
	/\btouch\b/,
	/>>?/,
	/\bapt(?:-get)?\s+install\b/,
	/\baptitude\s+install\b/,
	/\byum\s+install\b/,
	/\bdnf\s+install\b/,
	/\bbrew\s+install\b/,
	/\bpip\s+install\b/,
	/\bpip3\s+install\b/,
	/\bnpm\s+install\b/,
	/\bnpx\s+install\b/,
	/\byarn\s+add\b/,
	/\bdocker\s+rm\b/,
	/\bdocker\s+rmi\b/,
	/\bdocker\s+stop\b/,
	/\bdocker\s+kill\b/,
	/\bdocker\s+container\s+rm\b/,
	/\bkubectl\s+delete\b/,
	/\bsystemctl\s+stop\b/,
	/\bsystemctl\s+disable\b/,
	/\biptables\s+-F\b/,
	/\biptables\s+--flush\b/,
	/\buserdel\b/,
	/\busermod\b/,
	/\bgroupdel\b/
