//#region src/composables/useTunnelCredentials.ts
function needsCred(cfg) {
	if (cfg.type !== "ssh" && cfg.type !== "mosh" && cfg.type !== "sftp" && cfg.type !== "scp" && cfg.type !== "ftp") return false;
	if ((cfg.type === "ssh" || cfg.type === "mosh" || cfg.type === "scp" || cfg.type === "sftp") && (cfg.authType === "key" || cfg.authType === "keyText")) return false;
	if (cfg.authType === "identity") return false;
	return !cfg.user || !cfg.password;
}
function useTunnelCredentials() {
	const connectionStore = useConnectionStore();
	const { t } = useI18n();
	const showCredentialDialog = inject("showCredentialDialog", () => Promise.resolve(null));
	async function resolve(tunnelSSHConnId) {
		if (!tunnelSSHConnId) return {
			user: "",
			password: ""
		};
		const tunnelConn = connectionStore.connections.find((c) => c.id === tunnelSSHConnId);
		if (!tunnelConn) return {
			user: "",
			password: ""
		};
		if (!needsCred(tunnelConn)) return {
			user: tunnelConn.user || "",
			password: tunnelConn.password || ""
		};
		const result = await showCredentialDialog(t("credential.tunnelTitle"), t("credential.tunnelSubtitle", { name: tunnelConn.name }), ["user", "password"], tunnelConn.user, tunnelConn.password);
		if (!result) return null;
		const user = result.user || tunnelConn.user || "";
		const password = result.password || tunnelConn.password || "";
		if (result.action === "save_and_connect") await connectionStore.update(tunnelConn.id, {
			user,
			password
		});
		return {
			user,
			password
		};
	}
	return { resolveTunnelCredentials: resolve };
}
